//! Spec 0059 T10 (R56): the pure plan helpers of `plan gate` give the TS answer for every row of
//! `fixtures/plan_tables.json`, generated by `scripts/js/rust-oracle/plan-tables.mjs`. Each test
//! walks a whole table and reports every mismatching row at once.
// Covers: R56

use std::collections::BTreeSet;

use navori_core::diagnose::source_classify::classify_path;
use navori_core::plan::classify::{
    ClassifyInput, classify, declared_flags_from_signals, matches_critical_paths,
    normalize_repo_path,
};
use navori_core::plan::expected::{Expected, parse_expected};
use navori_core::spec::locate::locate_spec_dir;
use navori_core::spec::tasks::parse_tasks;
use serde_json::{Value, json};

fn table() -> Value {
    let text = include_str!("fixtures/plan_tables.json");
    serde_json::from_str(text).unwrap_or(Value::Null)
}

fn rows<'a>(table: &'a Value, key: &str) -> &'a [Value] {
    let rows = table[key].as_array().map_or(&[][..], Vec::as_slice);
    assert!(!rows.is_empty(), "table {key} is empty");
    rows
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(str::to_owned))
                .collect()
        })
        .unwrap_or_default()
}

fn report(name: &str, mismatches: &[String]) {
    assert!(
        mismatches.is_empty(),
        "{name}: {} rows differ from the TS:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}

#[test]
fn classify_path_and_normalize_match_the_ts_for_every_path() {
    let table = table();
    let local: BTreeSet<String> = ["local".to_owned()].into();
    let mut bad = Vec::new();
    for row in rows(&table, "classifyPath") {
        let path = row["path"].as_str().unwrap_or_default();
        let actual = json!({
            "path": path,
            "kind": classify_path(path, "", Some(&local)).map(|k| k.as_str()),
            "kindNoSkills": classify_path(path, "", None).map(|k| k.as_str()),
            "kindRooted": classify_path(path, "/repo/", None).map(|k| k.as_str()),
        });
        if &actual != row {
            bad.push(format!("  expected {row}\n  actual   {actual}"));
        }
    }
    for row in rows(&table, "normalizeRepoPath") {
        let input = row["input"].as_str().unwrap_or_default();
        let n = normalize_repo_path(input);
        let actual =
            json!({"input": input, "path": n.path, "absolute": n.absolute, "escapes": n.escapes});
        if &actual != row {
            bad.push(format!("  expected {row}\n  actual   {actual}"));
        }
    }
    report("paths", &bad);
}

#[test]
fn critical_path_globs_hit_the_same_paths_as_the_ts() {
    let table = table();
    let paths = strings(&Value::Array(
        rows(&table, "classifyPath")
            .iter()
            .map(|r| r["path"].clone())
            .collect(),
    ));
    let mut bad = Vec::new();
    for row in rows(&table, "matchesCriticalPaths") {
        let globs = strings(&row["globs"]);
        let hits: Vec<&String> = paths
            .iter()
            .filter(|p| matches_critical_paths(std::slice::from_ref(*p), &globs))
            .collect();
        let actual = json!({"globs": globs, "hits": hits});
        if &actual != row {
            bad.push(format!("  expected {row}\n  actual   {actual}"));
        }
    }
    report("globs", &bad);
}

#[test]
fn parse_expected_matches_the_ts_and_defers_only_js_regexes() {
    let table = table();
    let mut bad = Vec::new();
    for row in rows(&table, "parseExpected") {
        let text = row["text"].as_str().unwrap_or_default();
        let ts = &row["result"];
        let ok = match parse_expected(text) {
            Some(Expected::Free) => ts == &json!({"kind": "free"}),
            Some(Expected::Exit(code)) => ts == &json!({"kind": "exit", "code": code}),
            Some(Expected::Contains(t)) => ts == &json!({"kind": "contains", "text": t}),
            Some(Expected::Invalid(reason)) => ts == &json!({"kind": "invalid", "reason": reason}),
            // Rust cannot compile a JS RegExp: any TS verdict is fine, the caller delegates.
            Some(Expected::NeedsJs) => ts["kind"] == "matches" || ts["kind"] == "invalid",
            None => false,
        };
        if !ok {
            bad.push(format!(
                "  {text:?}: ts {ts}, rust {:?}",
                parse_expected(text)
            ));
        }
    }
    report("parseExpected", &bad);
}

#[test]
fn classify_gives_the_ts_score_level_and_signals_for_every_combination() {
    let table = table();
    let mut bad = Vec::new();
    for row in rows(&table, "classify") {
        let flag = |name: &str| row["flags"][name].as_bool().unwrap_or(false);
        let input = ClassifyInput {
            files: strings(&row["files"]),
            money_credentials_pii: flag("moneyCredentialsPii"),
            multi_repo: flag("multiRepo"),
            new_external_dependency: flag("newExternalDependency"),
            shared_contract: flag("sharedContract"),
            data_schema_migration: flag("dataSchemaMigration"),
            critical_area: flag("criticalArea"),
            critical_paths: strings(&row["criticalPaths"]),
            bug_without_root_cause: flag("bugWithoutRootCause"),
            local_skill_ids: Some(["local".to_owned()].into()),
        };
        let Some(result) = classify(&input) else {
            bad.push(format!("  {row}: rules failed to compile"));
            continue;
        };
        let d = declared_flags_from_signals(&result.signals);
        let actual = json!({
            "files": row["files"],
            "flags": row["flags"],
            "criticalPaths": row["criticalPaths"],
            "result": {
                "score": result.score,
                "level": result.level,
                "signals": result.signals,
                "nonTrivialCeiling": result.non_trivial_ceiling,
            },
            "declared": {
                "moneyCredentialsPii": d.money_credentials_pii,
                "multiRepo": d.multi_repo,
                "newExternalDependency": d.new_external_dependency,
                "sharedContract": d.shared_contract,
                "dataSchemaMigration": d.data_schema_migration,
                "criticalArea": d.critical_area,
                "bugWithoutRootCause": d.bug_without_root_cause,
            },
        });
        if &actual != row {
            bad.push(format!("  expected {row}\n  actual   {actual}"));
        }
    }
    report("classify", &bad);
}

#[test]
fn parse_tasks_reads_the_same_structure_as_the_ts_for_edges_and_real_specs() {
    let table = table();
    let mut bad = Vec::new();
    for row in rows(&table, "parseTasks") {
        let text = row["text"].as_str().unwrap_or_default();
        let Some(p) = parse_tasks(text) else {
            bad.push(format!("  {}: patterns failed to compile", row["name"]));
            continue;
        };
        let actual = json!({
            "name": row["name"],
            "text": text,
            "format": if p.deliveries_format { "deliveries" } else { "legacy" },
            "deliveries": p.deliveries.iter().map(|d| json!({"id": d.id, "milestones": d.milestones})).collect::<Vec<_>>(),
            "orphanTasks": p.orphan_tasks,
            "orphanCriteria": p.orphan_criteria,
            "malformed": p.malformed,
            "legacyTaskCount": p.legacy_task_count,
        });
        if &actual != row {
            let mut shown = actual.clone();
            shown["text"] = Value::Null;
            let mut expected = row.clone();
            expected["text"] = Value::Null;
            bad.push(format!("  expected {expected}\n  actual   {shown}"));
        }
    }
    report("parseTasks", &bad);
}

#[test]
fn locate_spec_dir_accepts_and_rejects_like_the_ts() {
    let table = table();
    let mut bad = Vec::new();
    for row in rows(&table, "locateSpecDir") {
        let specs_dir = row["specsDir"].as_str().unwrap_or_default();
        let spec = row["spec"].as_str().unwrap_or_default();
        let result = match locate_spec_dir("/repo", specs_dir, spec) {
            Some(Ok(dir)) => json!({"ok": true, "dir": dir}),
            Some(Err(why)) => json!({"ok": false, "why": why}),
            None => Value::Null,
        };
        let actual = json!({"specsDir": specs_dir, "spec": spec, "result": result});
        if &actual != row {
            bad.push(format!("  expected {row}\n  actual   {actual}"));
        }
    }
    report("locateSpecDir", &bad);
}

#[test]
fn the_roles_the_gate_never_gates_are_the_ts_roster() {
    let table = table();
    let ts = strings(&table["nonImplementerRoles"]);
    let rust: Vec<String> = navori_core::plan::roster::NON_IMPLEMENTER_ROLES
        .iter()
        .map(|r| (*r).to_owned())
        .collect();
    assert!(!ts.is_empty(), "the table has no roster");
    assert_eq!(rust, ts);
}
